// Una fila por foto, con el cuerpo ya armado para Amazon Nova Lite. Las fotos no se guardan en ningún lado.
const PROMPT="Eres un lector de exámenes escolares ya calificados. Mira la imagen y, para CADA pregunta numerada, indica si quedó CORRECTA o INCORRECTA según la marca del docente (visto/bien/puntaje completo = correcta; cruz/mal/0 = incorrecta). Si ves un puntaje por pregunta, devuélvelo también. IGNORA nombres de personas: solo devuelve el código del estudiante si aparece escrito como «Código» (por ejemplo EST-064); si no hay, usa null. No inventes preguntas que no veas. Responde SOLO con JSON válido, sin texto extra, con esta forma exacta: {\"codigo\":\"EST-064\",\"respuestas\":[{\"pregunta\":1,\"correcta\":true},{\"pregunta\":2,\"correcta\":false,\"puntaje\":0,\"puntaje_max\":10}]}";
const b=$input.first().json.body||$input.first().json;
return (b.imagenes||[]).map((im,i)=>{const formato=im.mime==='image/png'?'png':im.mime==='image/webp'?'webp':'jpeg';
  return {json:{evaluacion_id:b.evaluacion_id,hoja:i+1,req:{messages:[{role:'user',content:[{image:{format:formato,source:{bytes:im.b64}}},{text:PROMPT}]}],inferenceConfig:{maxTokens:1200,temperature:0}}}}});

// Une las hojas leídas y las valida. Si algo no se pudo leer, se avisa a la API (no se inventa nada).
const ev=$('Una fila por foto').first().json.evaluacion_id;
const hojas=[],fallas=[];
for(const [i,it] of $input.all().entries()){
  try{
    if(it.json.error) throw new Error('AWS: '+(it.json.error.message||it.json.error));
    let txt=(it.json.output?.message?.content||[]).map(c=>c.text||'').join('');
    txt=txt.replace(/```json|```/g,'').trim(); const j=JSON.parse(txt.slice(txt.indexOf('{'),txt.lastIndexOf('}')+1));
    const resp=(j.respuestas||[]).filter(r=>Number.isInteger(r.pregunta)&&r.pregunta>=1&&r.pregunta<=300).map(r=>{const o={pregunta:r.pregunta};
      if(typeof r.correcta==='boolean')o.correcta=r.correcta;
      if(typeof r.puntaje==='number'&&typeof r.puntaje_max==='number'&&r.puntaje_max>0){o.puntaje=r.puntaje;o.puntaje_max=r.puntaje_max}
      return o}).filter(o=>o.correcta!==undefined||o.puntaje!==undefined);
    const cod=typeof j.codigo==='string'&&/^[A-Za-z0-9-]{1,24}$/.test(j.codigo)?j.codigo:null;
    if(resp.length) hojas.push({codigo:cod,respuestas:resp}); else fallas.push('hoja '+(i+1)+' sin respuestas legibles');
  }catch(e){fallas.push('hoja '+(i+1)+': '+String(e.message).slice(0,80))}
}
return [{json:{evaluacion_id:ev,body:hojas.length?{hojas}:{error:('No se pudo leer: '+fallas.join('; ')).slice(0,290)}}}];
